-- ====================================================================
-- منصة أرض اللغة — الصف السابع + الصف الحادي عشر (أدبي/علمي)
-- كتب + وحدات + دروس — 2026-10-26
-- ملف تزايدي آمن (ON CONFLICT) — نفّذه مرة واحدة في Supabase SQL Editor
-- ====================================================================

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, color = EXCLUDED.color;

ON CONFLICT (grade) DO UPDATE SET gender_split = EXCLUDED.gender_split;

ON CONFLICT (grade_id, school_id) DO UPDATE SET sort_order = EXCLUDED.sort_order;

ON CONFLICT (grade, term) DO UPDATE SET unlocked_unit_order = EXCLUDED.unlocked_unit_order, note = EXCLUDED.note;

ON CONFLICT (id) DO UPDATE SET grade = EXCLUDED.grade, term = EXCLUDED.term, title = EXCLUDED.title, cover_url = EXCLUDED.cover_url, pdf_url = EXCLUDED.pdf_url, sort_order = EXCLUDED.sort_order;

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, lessons_count = EXCLUDED.lessons_count, duration = EXCLUDED.duration, color = EXCLUDED.color, icon = EXCLUDED.icon, sort_order = EXCLUDED.sort_order, published = EXCLUDED.published, grade = EXCLUDED.grade, term = EXCLUDED.term, cover_url = EXCLUDED.cover_url, avatar_url = EXCLUDED.avatar_url, status = EXCLUDED.status, is_locked = EXCLUDED.is_locked, is_visible = EXCLUDED.is_visible, section = EXCLUDED.section, school = EXCLUDED.school;

ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, title = EXCLUDED.title, description = EXCLUDED.description, position = EXCLUDED.position, content = EXCLUDED.content, published = EXCLUDED.published, lesson_type = EXCLUDED.lesson_type, cover_url = EXCLUDED.cover_url, images = EXCLUDED.images, html_content = EXCLUDED.html_content, html_file_url = EXCLUDED.html_file_url, status = EXCLUDED.status, is_locked = EXCLUDED.is_locked, is_visible = EXCLUDED.is_visible, grade = EXCLUDED.grade, term = EXCLUDED.term, school = EXCLUDED.school;

-- تم بحمد الله
