INSERT INTO public.lessons (id, course_id, title, description, position, content, published, lesson_type, cover_url, images, html_content, html_file_url, status, is_locked, is_visible, grade, term, school) VALUES
('d0710101-0000-4000-8000-000000000001', 'c0710100-0000-4000-8000-000000000001', 'الرحمة', 'درس استماع من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 1, '{"introduction":"«الرحمة» — نستمع إلى النص بوعي وانتباه، نحدد الفكرة العامة والأفكار الجزئية، ثم نجيب عن أسئلة الاستماع.","mainText":"محاور الدرس: الاستماع المنظم، تحديد الأفكار، تدوين الملاحظات، والإجابة عن الأسئلة.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'استماع', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710102-0000-4000-8000-000000000002', 'c0710100-0000-4000-8000-000000000001', 'رحمة الله بعباده', 'درس قراءة من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 2, '{"introduction":"«رحمة الله بعباده» — نقرأ النص قراءة فاهمة واعية: الفكرة العامة والأفكار الجزئية، المفردات والتراكيب، ثم أسئلة الفهم والاستيعاب.","mainText":"محاور الدرس: الفكرة العامة، الأفكار الجزئية، المفردات والتراكيب، أسئلة الفهم والاستيعاب.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'قراءة', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710103-0000-4000-8000-000000000003', 'c0710100-0000-4000-8000-000000000001', 'من وحي الحرمين', 'درس محفوظات من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 3, '{"introduction":"«من وحي الحرمين» — نحفظ النص حفظاً متقناً، نتدبر معناه وموسيقاه، ثم نؤديه أداءً معبراً.","mainText":"محاور الدرس: الحفظ المتقن، المعنى الإجمالي، الإلقاء المعبر، والتطبيق.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'محفوظات', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710104-0000-4000-8000-000000000004', 'c0710100-0000-4000-8000-000000000001', 'علامات الاسم (مراجعة)', 'درس قواعد لغوية من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 4, '{"introduction":"«علامات الاسم (مراجعة)» — نتعرف القاعدة وضابطها بالأمثلة والشواهد، ثم نطبق عليها بنماذج إعرابية وتدريبات متنوعة.","mainText":"محاور الدرس: القاعدة، الأمثلة والشواهد، النماذج الإعرابية، والتدريبات المتنوعة.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'قواعد لغوية', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710105-0000-4000-8000-000000000005', 'c0710100-0000-4000-8000-000000000001', 'الهمزة المتوسطة على نبرة', 'درس إملاء من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 5, '{"introduction":"«الهمزة المتوسطة على نبرة» — نضبط القاعدة الإملائية: الشرح المختصر، الأمثلة الموضحة، ثم الإملاء المنظور والاختباري.","mainText":"محاور الدرس: القاعدة الإملائية، الأمثلة، الإملاء المنظور، والإملاء الاختباري.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'إملاء', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710106-0000-4000-8000-000000000006', 'c0710100-0000-4000-8000-000000000001', 'الخط', 'درس خط من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 6, '{"introduction":"«الخط» — نتدرب على تحسين الخط العربي: رسم الحروف واتصالها، ومراعاة التناسب والوضوح.","mainText":"محاور الدرس: رسم الحروف، الاتصال، التناسب، والتدريب العملي.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'خط', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710107-0000-4000-8000-000000000007', 'c0710100-0000-4000-8000-000000000001', 'الفقرة', 'درس تعبير من الوحدة الأولى: رحمة الله بعباده — الصف السابع · الفصل الأول', 7, '{"introduction":"«الفقرة» — نتعلم خطوات الكتابة: التخطيط وجمع الأفكار، العرض المرتب بالشواهد، ثم المراجعة والتحسين.","mainText":"محاور الدرس: التخطيط، جمع الأفكار، العرض، الشواهد، والمراجعة والتحسين.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'تعبير', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
('d0710201-0000-4000-8000-000000000001', 'c0710200-0000-4000-8000-000000000002', 'الأماكن الدينية والتراثية في عكا', 'درس استماع من الوحدة الثانية: فلسطين قلب الأمة — الصف السابع · الفصل الأول', 1, '{"introduction":"«الأماكن الدينية والتراثية في عكا» — نستمع إلى النص بوعي وانتباه، نحدد الفكرة العامة والأفكار الجزئية، ثم نجيب عن أسئلة الاستماع.","mainText":"محاور الدرس: الاستماع المنظم، تحديد الأفكار، تدوين الملاحظات، والإجابة عن الأسئلة.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'استماع', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف السابع', 'الفصل الأول', ''),
